# Example of a simple dataclass
from dataclasses import dataclass

@dataclass
class Product:
    name: str
    price: float

# Example: creating an instance of a dataclass
@dataclass
class Book:
    title: str
    author: str

my_book = Book(title="1984", author="George Orwell")

# Example of a dataclass with type hints
@dataclass
class Book:
    title: str
    pages: int
    price: float

# Example: Adding a method to a dataclass
@dataclass
class Student:
    name: str
    grade: int

    def introduce(self):
        return f"I am {self.name} and I'm in grade {self.grade}."

# Example: Adding a method to a Pydantic model
class Book(BaseModel):
    title: str
    author: str

    def get_description(self):
        return f"'{self.title}' by {self.author}"

# Example of catching validation error
try:
    invalid_product = Product(name='Test', price='invalid')
except ValidationError as e:
    print(f'Validation error: {e}')
